from decimal import Decimal, ROUND_HALF_EVEN


def settle(amount: str) -> str:
    value = Decimal(amount).quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
    return str(value)


def batch_settle(amounts: list[str]) -> list[str]:
    return [settle(amount) for amount in amounts]

